WITH base AS (SELECT *, CASE WHEN discount_pct >= 0.32 THEN 'High' WHEN discount_pct >= 0.11 THEN 'Medium' ELSE 'Low' END AS discount_pct_level FROM promotions WHERE ends_on BETWEEN '2024-09-01' AND '2025-10-01') SELECT *, AVG(discount_pct) OVER (ORDER BY starts_on, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS discount_pct_avg_3, ROUND(discount_pct / SUM(discount_pct) OVER (PARTITION BY channel), 4) AS discount_pct_share, LEAD(discount_pct, 1) OVER (PARTITION BY promo_code ORDER BY discount_pct, id) AS next_discount_pct, SUM(discount_pct) OVER (PARTITION BY promo_code ORDER BY starts_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_discount_pct, LAST_VALUE(channel, TRUE) OVER (ORDER BY starts_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_channel FROM base;
